// The r001 handheld catalog (generated by scripts/art_library/crew_items/build.py). Only its data
// is read here, so the server module does not pull in the presentation helpers of crew-items.ts.
import handheldCatalog from "./crew-items-r001.json";
/** Handheld item families (inventory filters, detail panels, HUD). */
export type HandheldCategory = "weapon" | "medical" | "tool" | "utility";
/** Versioned laboratory item definitions. Grid dimensions are storage footprints,
 * distinct from physical mesh/collision dimensions. Every item is a stable instance. */
export interface InventoryDefinition {
  id: string;
  name: string;
  width: number;
  height: number;
  massKg: number;
  assetId: string;
  equipSlot?: EquipmentSlot;
  /** Native shared-rig component, authoritative only when an owned item is equipped. */
  characterComponentId?: string;
  /** Voxel-crew wardrobe item (crew-wardrobe.ts); visual only, like characterComponentId. */
  wardrobeId?: string;
  iconUrl?: string;
  pose?: "pistol" | "rifle";
  storage?: { width: number; height: number; maxMassKg: number };
  reservoir?: { capacityLitres: number; liquidType: string };
  /**
   * The r001 handheld (crew-items.ts) this item shows in the hand, on the holster and in the grid.
   * The ONLY legacy-to-r001 art mapping; presentation only.
   */
  crewItemId?: string;
  category?: HandheldCategory;
  /** Short role from the r001 catalogue ("Sidearm", "Close range" ...), shown beside the category. */
  role?: string;
  /** Held with both hands (support hand on the item). */
  twoHanded?: boolean;
  /** Most instances that may share one grid slot. Every item is one stable UUID instance today,
   * so nothing stacks yet (1). */
  maxStack?: number;
  /**
   * Created before r001 and owned by live players: its footprint and mass never grow (existing
   * placements and carried mass stay valid), so it may be smaller than the r001 art's footprint.
   */
  legacy?: boolean;
}

interface HandheldCatalogItem {
  id: string;
  name: string;
  subLabel: string;
  category: string;
  animationSet: string;
  twoHanded: boolean;
  grid: { width: number; height: number };
}
const HANDHELD_ITEMS = (
  handheldCatalog as unknown as { items: readonly HandheldCatalogItem[] }
).items;
const HANDHELD_ASSET_BASE = (handheldCatalog as { assetBase: string })
  .assetBase;
const HANDHELD_REVISION = (handheldCatalog as { revision: string }).revision;
/** Inventory grid icon of an r001 handheld (rendered at its footprint aspect). */
export function handheldGridIconUrl(crewItemId: string): string {
  return `${HANDHELD_ASSET_BASE}icons/grid/${crewItemId}.png?revision=${HANDHELD_REVISION}`;
}
/** "RAPID FIRE" -> "Rapid fire"; "MELEE • UTILITY" -> "Melee · utility". */
function handheldRole(item: HandheldCatalogItem): string {
  const text = item.subLabel.toLowerCase().replace(/\s*•\s*/g, " · ");
  return text.charAt(0).toUpperCase() + text.slice(1);
}
function handheldCategory(item: HandheldCatalogItem): HandheldCategory {
  if (item.category === "ballistic" || item.category === "energy")
    return "weapon";
  if (item.category === "medical" || item.category === "tool")
    return item.category;
  return "utility";
}
