const LAB_DEFINITIONS = LAB_BASE_DEFINITIONS.map(upgradeLegacy);
/**
 * Every r001 handheld is a real item (batch A, 2026-09-29): stable id = the r001 id, footprint from
 * the art (catalog `grid`), grid icon, category, hand/back slot, provisional mass, no stacking. The
 * two r001 ids that already name a lab item (`scanner`, `medkit`) keep that legacy definition.
 */
export const HANDHELD_DEFINITIONS: readonly InventoryDefinition[] =
  HANDHELD_ITEMS.map(
    (item) =>
      LAB_DEFINITIONS.find((d) => d.id === item.id) ?? {
        id: item.id,
        name: item.name,
        width: item.grid.width,
        height: item.grid.height,
        massKg: HANDHELD_MASS_KG[item.id] ?? 1,
        assetId: item.id,
        ...(handheldSlot(item) ? { equipSlot: handheldSlot(item) } : {}),
        iconUrl: handheldGridIconUrl(item.id),
        crewItemId: item.id,
        category: handheldCategory(item),
        role: handheldRole(item),
        twoHanded: item.twoHanded,
        maxStack: 1,
        ...(handheldPose(item) ? { pose: handheldPose(item) } : {}),
      },
  );
export const INVENTORY_DEFINITIONS: readonly InventoryDefinition[] = [
  ...LAB_DEFINITIONS,
  ...HANDHELD_DEFINITIONS.filter(
    (d) => !LAB_DEFINITIONS.some((lab) => lab.id === d.id),
  ),
  ...CHARACTER_ARMOR_DEFINITIONS,
  ...CREW_WARDROBE_DEFINITIONS,
];

/**
 * Operator stocking kits for `scripts/ship_cargo.py --kit` (operator_stock_ship_cargo). The
 * handheld kits hold one of every r001 item (new instances; nothing existing is touched).
 */
export const OPERATOR_ITEM_KITS: Readonly<Record<string, readonly string[]>> = {
  ...CREW_WARDROBE_KITS,
  "weapons-and-tools": HANDHELD_DEFINITIONS.map((d) => d.id),
  weapons: HANDHELD_DEFINITIONS.filter((d) => d.category === "weapon").map(
    (d) => d.id,
  ),
  "tools-and-utility": HANDHELD_DEFINITIONS.filter(
    (d) => d.category !== "weapon",
  ).map((d) => d.id),
};
export function inventoryDefinition(id: string): InventoryDefinition {
  const found = INVENTORY_DEFINITIONS.find(
    (definition) => definition.id === id,
  );
  if (!found) throw new Error("Unknown item definition");
  return found;
}
export const CHARACTER_CARRY_LIMIT_KG = 32;
export const LIQUID_DENSITY_KG_PER_LITRE: Readonly<Record<string, number>> = {
  fuel: 0.8,
  water: 1,
};
/** Equipment visuals are derived only from the filtered inventory projection. */
export function characterEquipmentFromInventory(
  items: readonly { definitionId: string; equipmentSlot: string }[],
) {
  const result: import("./character-components").EquippedCharacterComponents =
    {};
  for (const item of items) {
    const definition = INVENTORY_DEFINITIONS.find(
      (d) => d.id === item.definitionId,
    );
    if (definition?.equipSlot !== item.equipmentSlot || !item.equipmentSlot)
      continue;
    const id =
      definition.characterComponentId ??
      (definition.wardrobeId
        ? WARDROBE_DEFINITION_PREFIX + definition.wardrobeId
        : undefined) ??
      (definition.id === "field-pack" ? "engineer-back" : undefined);
    if (id && item.equipmentSlot !== "hand")
      result[
        item.equipmentSlot as import("./character-components").CharacterEquipmentSlot
      ] = id;
  }
  return result;
}
